// Step 1: Parse Command or Config Intent
const input = $input.first().json;

const userId = input.user_id;
const text = (input.text || '').trim();
const assistantName = input.assistant_name;

let action = 'welcome';
if (!assistantName || text.startsWith('/nombre') || input.setting_key === 'assistant_name') {
  action = 'set_name';
} else if (text.startsWith('/descanso') || input.setting_key === 'rest_mode') {
  action = 'toggle_rest';
} else if (text.startsWith('/configuracion')) {
  action = 'show_config';
}

return [{
  json: {
    ...input,
    config_action: action
  }
}];

const req = $('Parse Config Intent').first().json;
const settings = $input.first().json;

let responseText = '';
let rpcNameUpdate = null;

if (req.config_action === 'set_name') {
  const parts = req.text.split(' ');
  if (parts.length > 1) {
    const newName = parts.slice(1).join(' ').trim();
    rpcNameUpdate = newName;
    responseText = `¡Listo! A partir de ahora me llamo ${newName}.`;
  } else if (!settings.assistant_name) {
    responseText = '¡Hola! Soy tu secretaria virtual. ¿Cómo querés que me llame?';
  } else {
    responseText = `Actualmente me llamo ${settings.assistant_name}. Si querés cambiar mi nombre podés escribir /nombre [NuevoNombre].`;
  }
} else if (req.config_action === 'show_config') {
  responseText = `⚙️ Configuración actual:\n• Nombre: ${settings.assistant_name || 'Sin asignar'}\n• Horario de silencio: ${settings.quiet_hours_enabled ? `${settings.quiet_start_time} - ${settings.quiet_end_time}` : 'Desactivado'}\n• Modo descanso: ${settings.rest_mode_enabled ? 'Activo' : 'Inactivo'}`;
} else {
  responseText = `¡Hola! Soy ${settings.assistant_name || 'tu secretaria virtual'}. ¿En qué puedo ayudarte hoy?`;
}

return [{
  json: {
    ...req,
    new_name_candidate: rpcNameUpdate,
    response_text: responseText
  }
}];

const cfg = $('Handle Config Action').first().json;

return [{
  json: {
    ok: true,
    status: 'completed',
    correlation_id: cfg.correlation_id,
    data: {
      message_sent: true,
      response_text: cfg.response_text,
      assistant_name: cfg.new_name_candidate || cfg.assistant_name
    }
  }
}];
